// Combine pre-computed unknown features + corpus features into one payload.
const unknown = $('Unknown Features').first().json;
const corpus = $('Corpus Features').first().json;

// Compact corpus: keep features per sample but trim long arrays so the
// prompt stays manageable. We keep the most useful scalars + a handful of
// the most-frequent function words and POS bigrams for comparison.
function topN(dict, n) {
  if (!dict || typeof dict !== 'object') return {};
  const entries = Object.entries(dict)
    .filter(([, v]) => typeof v === 'number' && v > 0)
    .sort((a, b) => b[1] - a[1])
    .slice(0, n);
  return Object.fromEntries(entries);
}

function compact(features) {
  if (!features) return {};
  return {
    vocab_richness: features.vocab_richness,
    top_function_words: topN(features.function_word_freqs?.rates_per_1000, 15),
    top_pos_bigrams: topN(features.pos_distribution?.bigrams, 12),
    pos_unigrams: features.pos_distribution?.unigrams,
    punctuation: features.punctuation_profile?.rates_per_1000,
    sentence_stats: {
      n_sents: features.sentence_length_stats?.n_sents,
      mean: features.sentence_length_stats?.mean,
      median: features.sentence_length_stats?.median,
      stdev: features.sentence_length_stats?.stdev,
    },
  };
}

return [{
  json: {
    unknown: compact(unknown),
    corpus: (corpus.authors || []).map(a => ({
      author: a.author,
      n_samples: a.samples.length,
      samples: a.samples.map(s => ({
        sample_id: s.sample_id,
        n_tokens: s.n_tokens,
        features: compact(s.features),
      })),
    })),
  },
}];
